import toast from "react-hot-toast";
// eslint-disable-next-line import/no-unresolved
import { Toast } from "react-hot-toast/dist/core/types";
import Icon from "Components/Icon";

type ToastOptions = Partial<Pick<Toast, "id" | "icon" | "duration" | "role" | "ariaLive" | "className" | "style" | "iconTheme">>

const toastDefaultOptions: ToastOptions = {
  duration: 6000,
};

const iconSuccess = (<Icon icon="check-circle" className="text-success" />);
const iconWarning = (<Icon icon="exclamation-triangle" className="text-warning" />);
const iconInfo = (<Icon icon="exclamation-circle" className="text-info" />);
const iconError = (<Icon icon="times-circle" className="text-danger" />);

const notification = {
  show(message: string, options: ToastOptions = {}) {
    toast(message, { ...toastDefaultOptions, ...options });
  },

  success(message: string, options: ToastOptions = {}) {
    this.show(message, { icon: iconSuccess, ...options });
  },

  info(message: string, options: ToastOptions = {}) {
    this.show(message, { icon: iconInfo, ...options });
  },

  warning(message: string, options: ToastOptions = {}) {
    this.show(message, { icon: iconWarning, ...options });
  },

  error(message: string, options: ToastOptions = {}) {
    this.show(message, { icon: iconError, ...options });
  },
};

export default notification;
